#!/usr/bin/env python3
"""Generates THIRD_PARTY_NOTICES.md from the profile manifests (presets/profile/*.rice.toml).

    python3 tools/third-party-notices.py          # update
    python3 tools/third-party-notices.py --check  # check only (exit 1 = stale)
"""

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT / "python"))

from hyprsetup import rice  # noqa: E402

OUT = "THIRD_PARTY_NOTICES.md"

HEADER = """\
# Third-party notices

<!-- Generated by tools/third-party-notices.py from presets/profile/*.rice.toml; do not edit by hand. -->

Souprland's own code is MIT-licensed (see [LICENSE](LICENSE)). The author profiles
install other people's dotfiles, pinned to one commit each. Those files keep their
own licenses; they are listed below.

- **Shipped** sources are archived under `vendor/rices/` (installed paths only, plus
  the repo's license file). Their license is the one in the repo **at the pinned
  commit**; later upstream versions may be licensed differently.
- **Fetched** sources had no license at the pinned commit, so they are not
  redistributed: the installer downloads them from the author's repo on your machine.
- **Media is never shipped.** Images, video and audio over 64 KB are left out of every
  archive and downloaded from the author's repo at install time. Dotfile repos often
  include art (game, anime or film characters, franchise wallpapers) that the
  dotfile author does not own and their license cannot cover.

| Source | Commit | License | Distribution | Used by |
|---|---|---|---|---|
"""


def render() -> str:
    rows: dict[tuple[str, str], list] = {}
    for name in rice.all_profiles(ROOT):
        if rice.is_imported(ROOT, name):
            continue
        manifest = rice.load(ROOT, name)
        for (url, commit), license_ in manifest.source_licenses().items():
            shipped = bool(license_ and rice.vendor_archive(manifest.vendor, url, commit))
            entry = rows.setdefault((url, commit), [license_, shipped, []])
            entry[0] = entry[0] or license_
            entry[1] = entry[1] or shipped
            entry[2].append(name)
    lines = [HEADER.rstrip("\n")]
    for (url, commit), (license_, shipped, users) in sorted(
            rows.items(), key=lambda row: row[0][0].lower()):
        repo = url.removeprefix("https://github.com/")
        lines.append(f"| [{repo}]({url}) | [`{commit[:7]}`]({url}/tree/{commit}) "
                     f"| {license_ or 'none stated'} "
                     f"| {'shipped' if shipped else 'fetched'} "
                     f"| {', '.join(sorted(set(users)))} |")
    return "\n".join(lines) + "\n"


def main() -> int:
    path = ROOT / OUT
    text = render()
    current = path.read_text(encoding="utf-8") if path.is_file() else ""
    if current == text:
        return 0
    if "--check" in sys.argv[1:]:
        print(f"out of date: {OUT} — python3 tools/third-party-notices.py", file=sys.stderr)
        return 1
    path.write_text(text, encoding="utf-8")
    print(f"updated: {OUT}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
